AsciiString HotKeyManager::searchHotKey(const UnicodeString &uStr)
{
	if (uStr.isEmpty())
		return AsciiString::TheEmptyString;

	const unsigned short *marker = uStr.str();
	while (marker && *marker)
	{
		if (*marker == L'&')
		{
			UnicodeString tmp = UnicodeString::TheEmptyString;
			tmp.concat(*(marker + 1));
			AsciiString retStr;
			retStr.translate(tmp);
			return retStr;
		}
		marker++;
	}
	return AsciiString::TheEmptyString;
}

