// FUNCTION: BFME2 0x003593E8 size=366 name=?executeHotKey@HotKeyManager@@QAE_NABVAsciiString@@_N@Z evidence=N:ledger tier=B hypothesis:K
bool HotKeyManager::executeHotKey(const AsciiString &keyIn, bool shift)
{
	if (TheGameLogic->isGamePaused() || !TheInGameUI->getInputEnabled() || TheInGameUI->isQuitMenuVisible())
		return false;

	AsciiString key = keyIn;
	key.toLower();
	bool executed = false;
	bool failed = false;
	HotKeyAction *action = 0;

	HotKeyMap::iterator it = m_hotKeys.find(key);
	action = (it == m_hotKeys.end()) ? 0 : it->second.get();
	if (!action)
	{
		it = m_secondaryHotKeys.find(key);
		action = (it == m_secondaryHotKeys.end()) ? 0 : it->second.get();
	}
	if (action && !action->tryExecute(shift))
	{
		if (action->tryExecuteAlternate(shift))
			executed = true;
		else
			failed = true;
	}

	if (!executed)
	{
		key.toUpper();
		it = m_hotKeys.find(key);
		action = (it == m_hotKeys.end()) ? 0 : it->second.get();
		if (!action)
		{
			it = m_secondaryHotKeys.find(key);
			action = (it == m_secondaryHotKeys.end()) ? 0 : it->second.get();
		}
		if (action && !action->tryExecute(shift))
		{
			if (action->tryExecuteAlternate(shift))
				executed = true;
			else
				failed = true;
		}
	}

	if (executed)
	{
		if (action->afterExecute(shift))
			rva00358A53();
		return true;
	}

	if (failed)
		rva00358ACB();
	return false;
}

// FUNCTION: BFME2 0x00359556 size=343 name=?translate@HotKeyManager@@QAE?AW4GameMessageDisposition@@PBVGameMessage@@@Z evidence=N:ledger tier=B hypothesis:K
GameMessageDisposition HotKeyManager::translate(const GameMessage *msg)
{
	int type = msg->getType();
	HotKeyMessageActionMap::iterator it = m_messageActions.find(type);
	if (it != m_messageActions.end())
	{
		if (!it->second.get()->tryExecute(false))
		{
			if (it->second.get()->tryExecuteAlternate(false))
			{
				if (it->second.get()->afterExecute(false))
					rva00358A53();
			}
			else
				rva00358ACB();
			return DESTROY_MESSAGE;
		}
	}

	if (type == GameMessage::MSG_RAW_KEY_UP)
	{
		int keyState = msg->getArgument(1)->integer;
		int modState = 0;
		bool shift = false;
		if (keyState & KEY_STATE_SHIFT)
		{
			modState |= SHIFT;
			shift = true;
		}
		if (keyState & KEY_STATE_CONTROL)
		{
			modState |= CTRL;
			shift = false;
		}
		if (keyState & KEY_STATE_ALT)
		{
			modState |= ALT;
			shift = false;
		}
		if (modState != 0 && !shift)
			return KEEP_MESSAGE;

		unsigned short key = TheKeyboard->getPrintableKey((unsigned char)msg->getArgument(0)->integer, 0);
		UnicodeString uKey;
		uKey.set(key);
		AsciiString aKey;
		aKey.translate(uKey);
		if (executeHotKey(aKey, shift))
			return DESTROY_MESSAGE;
	}
	return KEEP_MESSAGE;
}

